      ro: ["Pus în funcțiune la 1 octombrie 1936.", "Ultimul far controlat manual din Africa de Sud.", "Numit după o barcă naufragiată în 1829.", "Înălțime: turn de zidărie de 15 metri.", "Raza de lumină: 32 de mile marine.", "Situat în Rezervația Naturală Cape Columbine."],
